import React from "react";
import Gallery from "../Components/Gallery";

function Home() {
  return (
    <div className="home-container">
      <section>
        <h1 className="welcome-message" style={homeStyles.welcomeMessage}>
          Three Little Ladies Bakery
        </h1>

        <p>
          Welcome to Three Little Ladies Bakery, where every sweet treat is
          baked with love and passion!
        </p>

        <button
          onClick={() => (window.location.href = "/menu")}
          style={homeStyles.button}
        >
          View Our Menu
        </button>
      </section>

      <section>
        <h2>Our Story </h2>
        <p>
          Three Little Ladies Bakery was founded in 2010 by three best friends
          who shared a passion for baking and creating delicious treats for
          their community. What started as a small home-based business has grown
          into a beloved local institution, known for our fresh-baked goods and
          friendly service.
        </p>
      </section>

      <section>
        <Gallery />
      </section>
    </div>
  );
}

export default Home;

const homeStyles = {
  welcomeMessage: {
    fontSize: "36px",
    margin: "20px 0",
  },
  gallery: {
    maxWidth: "800px",
    margin: "0 auto",
  },
};
